                           'iam.refresh_tokens', 'iam.login_events', 'iam.password_reset_tokens',
                           'platform.tenants', 'platform.tenant_settings', 'platform.platform_users',
                           'platform.platform_roles'] LOOP
    EXECUTE format('DROP POLICY IF EXISTS auth_fn_all ON %s', t);
    EXECUTE format('CREATE POLICY auth_fn_all ON %s FOR ALL TO rag_auth_fn USING (true) WITH CHECK (true)', t);
  END LOOP;
END $$;
