-- 1. Credential lookup (login).  Returns the password hash so the API can verify it
--    with a constant-time KDF comparison; the hash never leaves the server.
CREATE OR REPLACE FUNCTION app.auth_lookup_account(p_email text)
RETURNS TABLE (account_id uuid, display_name text, password_hash text, auth_provider text, status text,
               locked_until timestamptz, mfa_enabled boolean, mfa_secret_enc text, failed_login_count integer)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
  SELECT a.account_id, a.display_name, a.password_hash, a.auth_provider, a.status, a.locked_until,
         a.mfa_enabled, a.mfa_secret_enc, a.failed_login_count
    FROM iam.user_accounts a WHERE a.email = p_email::public.citext
$$;

CREATE OR REPLACE FUNCTION app.auth_lookup_external(p_provider text, p_subject text, p_email text)
RETURNS TABLE (account_id uuid, display_name text, status text)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
  SELECT a.account_id, a.display_name, a.status FROM iam.user_accounts a
   WHERE (a.auth_provider = p_provider AND a.external_subject = p_subject)
      OR (a.external_subject IS NULL AND a.auth_provider = p_provider AND a.email = p_email::public.citext)
   ORDER BY (a.external_subject IS NOT NULL) DESC LIMIT 1
$$;

-- 2. Record a login attempt; applies lockout after p_lock_threshold consecutive failures.
CREATE OR REPLACE FUNCTION app.auth_record_login(p_account_id uuid, p_success boolean, p_reason text, p_method text,
                                                 p_ip inet, p_user_agent text, p_email_hash text,
                                                 p_lock_threshold integer, p_lock_minutes integer)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
BEGIN
  IF p_account_id IS NOT NULL THEN
    IF p_success THEN
      UPDATE iam.user_accounts SET failed_login_count = 0, locked_until = NULL, last_login_at = now()
       WHERE account_id = p_account_id;
    ELSE
      UPDATE iam.user_accounts
         SET failed_login_count = failed_login_count + 1,
             locked_until = CASE WHEN failed_login_count + 1 >= p_lock_threshold
                                 THEN now() + make_interval(mins => p_lock_minutes) ELSE locked_until END
       WHERE account_id = p_account_id;
    END IF;
  END IF;
  INSERT INTO iam.login_events (account_id, email_hash, success, reason, auth_method, ip, user_agent)
  VALUES (p_account_id, p_email_hash, p_success, p_reason, p_method, p_ip, left(p_user_agent, 300));
END $$;

-- 3. Membership resolution (tenant selection).
CREATE OR REPLACE FUNCTION app.auth_list_memberships(p_account_id uuid)
RETURNS TABLE (tenant_id uuid, tenant_code text, tenant_name text, tenant_status text, membership_status text,
               user_id uuid, user_status text, is_default boolean)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
  SELECT m.tenant_id, t.code, t.name, t.status, m.status, m.user_id, u.status, m.is_default
    FROM iam.tenant_memberships m
    JOIN platform.tenants t ON t.tenant_id = m.tenant_id
    JOIN iam.users u ON u.user_id = m.user_id AND u.tenant_id = m.tenant_id
   WHERE m.account_id = p_account_id
   ORDER BY m.is_default DESC, t.name
$$;

CREATE OR REPLACE FUNCTION app.auth_platform_role(p_account_id uuid) RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
  SELECT r.code FROM platform.platform_users p JOIN platform.platform_roles r ON r.role_id = p.role_id
   WHERE p.account_id = p_account_id AND p.status = 'active'
$$;

-- 4. Session creation.  A tenant-bound session requires an active membership in an
--    operational tenant and an active tenant user.
CREATE OR REPLACE FUNCTION app.auth_create_session(p_account_id uuid, p_tenant_id uuid, p_refresh_hash text,
                                                   p_absolute_expires timestamptz, p_refresh_expires timestamptz,
                                                   p_mfa_verified boolean, p_method text, p_ip inet, p_user_agent text)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE v_session uuid;
BEGIN
  IF p_tenant_id IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM iam.tenant_memberships m
         JOIN platform.tenants t ON t.tenant_id = m.tenant_id
         JOIN iam.users u ON u.user_id = m.user_id
        WHERE m.account_id = p_account_id AND m.tenant_id = p_tenant_id AND m.status = 'active'
          AND u.status = 'active' AND t.status IN ('active', 'trial')) THEN
    RAISE EXCEPTION 'no active membership for tenant' USING ERRCODE = 'insufficient_privilege';
  END IF;
  INSERT INTO iam.sessions (account_id, tenant_id, absolute_expires_at, mfa_verified_at, auth_method, ip, user_agent)
  VALUES (p_account_id, p_tenant_id, p_absolute_expires, CASE WHEN p_mfa_verified THEN now() END, p_method, p_ip,
          left(p_user_agent, 300))
  RETURNING session_id INTO v_session;
  INSERT INTO iam.refresh_tokens (session_id, token_hash, expires_at) VALUES (v_session, p_refresh_hash, p_refresh_expires);
  RETURN v_session;
END $$;

-- 5. Refresh-token rotation with reuse detection.
CREATE OR REPLACE FUNCTION app.auth_rotate_refresh(p_old_hash text, p_new_hash text, p_refresh_expires timestamptz)
RETURNS TABLE (result text, session_id uuid, account_id uuid, tenant_id uuid, mfa_verified_at timestamptz)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
#variable_conflict use_column
DECLARE rt iam.refresh_tokens%ROWTYPE; s iam.sessions%ROWTYPE;
BEGIN
  SELECT * INTO rt FROM iam.refresh_tokens WHERE token_hash = p_old_hash FOR UPDATE;
  IF NOT FOUND THEN RETURN QUERY SELECT 'invalid'::text, NULL::uuid, NULL::uuid, NULL::uuid, NULL::timestamptz; RETURN; END IF;
  SELECT * INTO s FROM iam.sessions WHERE iam.sessions.session_id = rt.session_id FOR UPDATE;
  IF rt.used_at IS NOT NULL OR rt.revoked_at IS NOT NULL THEN
    -- A rotated token was presented again: assume theft, revoke the whole session.
    UPDATE iam.sessions SET revoked_at = now(), revoked_reason = 'refresh_token_reuse'
     WHERE iam.sessions.session_id = rt.session_id AND revoked_at IS NULL;
    UPDATE iam.refresh_tokens SET revoked_at = now() WHERE iam.refresh_tokens.session_id = rt.session_id AND revoked_at IS NULL;
    RETURN QUERY SELECT 'reuse_detected'::text, s.session_id, s.account_id, s.tenant_id, NULL::timestamptz; RETURN;
  END IF;
  IF rt.expires_at <= now() OR s.revoked_at IS NOT NULL OR s.absolute_expires_at <= now() THEN
    RETURN QUERY SELECT 'expired'::text, s.session_id, s.account_id, s.tenant_id, NULL::timestamptz; RETURN;
  END IF;
  UPDATE iam.refresh_tokens SET used_at = now() WHERE token_id = rt.token_id;
  INSERT INTO iam.refresh_tokens (session_id, token_hash, expires_at)
  VALUES (s.session_id, p_new_hash, LEAST(p_refresh_expires, s.absolute_expires_at));
  UPDATE iam.sessions SET last_seen_at = now() WHERE iam.sessions.session_id = s.session_id;
  RETURN QUERY SELECT 'ok'::text, s.session_id, s.account_id, s.tenant_id, s.mfa_verified_at;
END $$;

-- 6. Per-request validation: session alive (idle + absolute timeout), membership
--    active, tenant operational, tenant user active, platform role.
CREATE OR REPLACE FUNCTION app.auth_resolve_request(p_account_id uuid, p_session_id uuid, p_tenant_id uuid)
RETURNS TABLE (session_ok boolean, session_reason text, membership_ok boolean, tenant_status text,
               user_id uuid, user_status text, platform_role text, mfa_verified_at timestamptz)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
#variable_conflict use_column
DECLARE s iam.sessions%ROWTYPE; v_idle integer := 30; v_reason text := 'ok';
BEGIN
  SELECT * INTO s FROM iam.sessions WHERE iam.sessions.session_id = p_session_id AND iam.sessions.account_id = p_account_id;
  IF NOT FOUND THEN v_reason := 'unknown_session';
  ELSIF s.revoked_at IS NOT NULL THEN v_reason := 'revoked';
  ELSIF s.absolute_expires_at <= now() THEN v_reason := 'expired';
  ELSIF s.tenant_id IS DISTINCT FROM p_tenant_id THEN v_reason := 'tenant_mismatch';
  ELSE
    SELECT ts.session_idle_minutes INTO v_idle FROM platform.tenant_settings ts WHERE ts.tenant_id = p_tenant_id;
    IF s.last_seen_at < now() - make_interval(mins => COALESCE(v_idle, 30)) THEN
      v_reason := 'idle_timeout';
      UPDATE iam.sessions SET revoked_at = now(), revoked_reason = 'idle_timeout' WHERE iam.sessions.session_id = s.session_id;
    ELSIF s.last_seen_at < now() - interval '30 seconds' THEN
      UPDATE iam.sessions SET last_seen_at = now() WHERE iam.sessions.session_id = s.session_id;
    END IF;
  END IF;
  RETURN QUERY
    SELECT v_reason = 'ok', v_reason,
           COALESCE(m.status = 'active', false), t.status, u.user_id, u.status,
           (SELECT r.code FROM platform.platform_users p JOIN platform.platform_roles r ON r.role_id = p.role_id
             WHERE p.account_id = p_account_id AND p.status = 'active'),
           s.mfa_verified_at
      FROM (SELECT 1) one
      LEFT JOIN iam.tenant_memberships m ON m.account_id = p_account_id AND m.tenant_id = p_tenant_id
      LEFT JOIN platform.tenants t ON t.tenant_id = p_tenant_id
      LEFT JOIN iam.users u ON u.user_id = m.user_id;
END $$;

CREATE OR REPLACE FUNCTION app.auth_mark_mfa(p_session_id uuid, p_account_id uuid) RETURNS void
LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
  UPDATE iam.sessions SET mfa_verified_at = now() WHERE session_id = p_session_id AND account_id = p_account_id AND revoked_at IS NULL
$$;

CREATE OR REPLACE FUNCTION app.auth_revoke_session(p_session_id uuid, p_account_id uuid, p_reason text) RETURNS void
LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
  UPDATE iam.sessions SET revoked_at = now(), revoked_reason = p_reason
   WHERE session_id = p_session_id AND account_id = p_account_id AND revoked_at IS NULL;
  UPDATE iam.refresh_tokens SET revoked_at = now() WHERE session_id = p_session_id AND revoked_at IS NULL;
$$;

-- Revoke every session of an account (deactivation, password reset, admin action).
-- Tenant admins may only revoke sessions bound to their own tenant.
CREATE OR REPLACE FUNCTION app.auth_revoke_account_sessions(p_account_id uuid, p_reason text) RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE n integer;
BEGIN
  IF app.current_access_mode() IN ('tenant_admin', 'platform_provisioning') THEN
    UPDATE iam.sessions SET revoked_at = now(), revoked_reason = p_reason
     WHERE account_id = p_account_id AND tenant_id = app.current_tenant_id() AND revoked_at IS NULL;
  ELSIF app.is_platform_admin() OR app.current_account_id() = p_account_id THEN
    UPDATE iam.sessions SET revoked_at = now(), revoked_reason = p_reason WHERE account_id = p_account_id AND revoked_at IS NULL;
  ELSE
    RAISE EXCEPTION 'not allowed to revoke sessions' USING ERRCODE = 'insufficient_privilege';
  END IF;
  GET DIAGNOSTICS n = ROW_COUNT;
  UPDATE iam.refresh_tokens r SET revoked_at = now() FROM iam.sessions s
   WHERE r.session_id = s.session_id AND s.account_id = p_account_id AND s.revoked_at IS NOT NULL AND r.revoked_at IS NULL;
  RETURN n;
END $$;

-- 7. Password reset workflow (FR / extension 7.2): the token is created by a tenant
--    admin for a member of THEIR tenant (or by the account holder), consumed
--    without authentication, single-use, time-limited; consumption revokes sessions.
CREATE OR REPLACE FUNCTION app.auth_create_reset_token(p_account_id uuid, p_token_hash text, p_expires timestamptz)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
BEGIN
  IF NOT (app.current_account_id() = p_account_id
          OR app.is_platform_admin()
          OR (app.current_access_mode() IN ('tenant_admin', 'platform_provisioning') AND EXISTS (
                SELECT 1 FROM iam.tenant_memberships m WHERE m.account_id = p_account_id
                                                      AND m.tenant_id = app.current_tenant_id()))) THEN
    RAISE EXCEPTION 'not allowed to reset this account' USING ERRCODE = 'insufficient_privilege';
  END IF;
  UPDATE iam.password_reset_tokens SET used_at = now() WHERE account_id = p_account_id AND used_at IS NULL;
  INSERT INTO iam.password_reset_tokens (token_hash, account_id, requested_by, expires_at)
  VALUES (p_token_hash, p_account_id, app.current_account_id(), p_expires);
END $$;

CREATE OR REPLACE FUNCTION app.auth_consume_reset_token(p_token_hash text, p_new_password_hash text) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE v_account uuid;
BEGIN
  UPDATE iam.password_reset_tokens SET used_at = now()
   WHERE token_hash = p_token_hash AND used_at IS NULL AND expires_at > now()
  RETURNING account_id INTO v_account;
  IF v_account IS NULL THEN RETURN NULL; END IF;
  UPDATE iam.user_accounts SET password_hash = p_new_password_hash, password_changed_at = now(),
         failed_login_count = 0, locked_until = NULL
   WHERE account_id = v_account AND auth_provider = 'local';
  UPDATE iam.sessions SET revoked_at = now(), revoked_reason = 'password_reset' WHERE account_id = v_account AND revoked_at IS NULL;
  RETURN v_account;
END $$;

-- 8. Link an existing global identity when an administrator adds a user who
--    already exists in another tenant.  Returns only the identifier.
CREATE OR REPLACE FUNCTION app.account_id_for_email(p_email text) RETURNS uuid
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
BEGIN
  IF NOT (app.current_access_mode() IN ('tenant_admin', 'platform_provisioning') OR app.is_platform_admin()) THEN
    RAISE EXCEPTION 'administrative context required' USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN (SELECT account_id FROM iam.user_accounts WHERE email = p_email::public.citext);
END $$;

GRANT CREATE ON SCHEMA app TO rag_auth_fn;   -- transiently, to transfer ownership
DO $$
DECLARE f text;
BEGIN
  FOREACH f IN ARRAY ARRAY[
    'app.auth_lookup_account(text)', 'app.auth_lookup_external(text,text,text)',
    'app.auth_record_login(uuid,boolean,text,text,inet,text,text,integer,integer)',
    'app.auth_list_memberships(uuid)', 'app.auth_platform_role(uuid)',
    'app.auth_create_session(uuid,uuid,text,timestamptz,timestamptz,boolean,text,inet,text)',
    'app.auth_rotate_refresh(text,text,timestamptz)', 'app.auth_resolve_request(uuid,uuid,uuid)',
    'app.auth_mark_mfa(uuid,uuid)', 'app.auth_revoke_session(uuid,uuid,text)',
    'app.auth_revoke_account_sessions(uuid,text)', 'app.auth_create_reset_token(uuid,text,timestamptz)',
    'app.auth_consume_reset_token(text,text)', 'app.account_id_for_email(text)'] LOOP
    EXECUTE format('ALTER FUNCTION %s OWNER TO rag_auth_fn', f);
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC', f);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO rag_app', f);
  END LOOP;
END $$;
REVOKE CREATE ON SCHEMA app FROM rag_auth_fn;

